// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Doador) predicate.Doador {
	return predicate.Doador(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Doador) predicate.Doador {
	return predicate.Doador(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Doador) predicate.Doador {
	return predicate.Doador(sql.NotPredicates(p))
}
